{
  "schema_version": 1,
  "observations": [
    {
      "key": "obs_1",
      "facet": "mechanism",
      "statement": "When no appropriate index is available, an ORDER BY query gathers the output and runs it through a sorter.",
      "start_line": 1,
      "end_line": 1
    },
    {
      "key": "obs_2",
      "facet": "property",
      "statement": "The sorter used for indexless ORDER BY can require substantial temporary storage.",
      "start_line": 1,
      "end_line": 1
    },
    {
      "key": "obs_3",
      "facet": "mechanism",
      "statement": "If an index is available on the ORDER BY column, SQLite can scan that index and perform rowid lookups instead of sorting.",
      "start_line": 1,
      "end_line": 1
    },
    {
      "key": "obs_4",
      "facet": "property",
      "statement": "Both index scan and indexless sort can require work proportional to N log N.",
      "start_line": 3,
      "end_line": 3
    },
    {
      "key": "obs_5",
      "facet": "mechanism",
      "statement": "SQLite uses a cost-based query planner and estimates the total time for each plan.",
      "start_line": 3,
      "end_line": 3
    },
    {
      "key": "obs_6",
      "facet": "precondition",
      "statement": "The choice between index scan and indexless sort can depend on table size and WHERE-clause constraints.",
      "start_line": 3,
      "end_line": 3
    },
    {
      "key": "obs_7",
      "facet": "property",
      "statement": "The indexed sort generally uses less temporary storage because it does not accumulate the entire result before sorting.",
      "start_line": 3,
      "end_line": 3
    },
    {
      "key": "obs_8",
      "facet": "mechanism",
      "statement": "A covering index can avoid the rowid lookups.",
      "start_line": 5,
      "end_line": 5
    },
    {
      "key": "obs_9",
      "facet": "property",
      "statement": "Using a covering index can reduce the cost further.",
      "start_line": 5,
      "end_line": 5
    }
  ],
  "claims": [
    {
      "key": "claim_1",
      "status": "DERIVED_INTERPRETATION",
      "statement": "SQLite's query planner selects between index-based retrieval and sorting based on estimated total time, which is influenced by table size and WHERE-clause constraints, despite both methods having similar asymptotic complexity (N log N).",
      "supported_by": [
        "obs_4",
        "obs_5",
        "obs_6"
      ]
    },
    {
      "key": "claim_2",
      "status": "DERIVED_INTERPRETATION",
      "statement": "Index-based ORDER BY is preferred over sorting primarily for reduced temporary storage usage, as it avoids accumulating the entire result set, whereas covering indices offer further cost reduction by eliminating rowid lookups.",
      "supported_by": [
        "obs_2",
        "obs_3",
        "obs_7",
        "obs_8",
        "obs_9"
      ]
    }
  ],
  "questions": []
}
